#!/usr/bin/env bash
# Generated by gemma4-bench for run 20261018-0126-sgl-b-tau2cfg-lk-h200-1x01-livekit-c4; the measurement lives in recipes/run_cell.sh.
set -o pipefail
source "$(dirname "$0")/../../benchmark_lib.sh"
check_env_vars CONC PORT INFMAX_CONTAINER_WORKSPACE RESULT_FILENAME
export BENCH_DIR="$INFMAX_CONTAINER_WORKSPACE/bench-20261018-0126-sgl-b-tau2cfg-lk-h200-1x01-livekit-c4"
rm -rf "$BENCH_DIR"; mkdir -p "$BENCH_DIR/datasets"
cp -r "$INFMAX_CONTAINER_WORKSPACE/benchmarks/gemma4j/20261018-0126-sgl-b-tau2cfg-lk-h200-1x01-livekit-c4/." "$BENCH_DIR/"
install_agentic_deps || exit 1
for v in V1 V2; do
  rel=$(sed -n "s/^LIVEKIT_${v}_FILE=//p" "$BENCH_DIR/run.env"); [ -n "$rel" ] || continue
  rev=$(sed -n "s/^LIVEKIT_${v}_REV=//p" "$BENCH_DIR/run.env"); want=$(sed -n "s/^LIVEKIT_${v}_SHA=//p" "$BENCH_DIR/run.env")
  src=$("$AIPERF_PYTHON" -c "import os, sys; from huggingface_hub import hf_hub_download; print(hf_hub_download(sys.argv[1], sys.argv[2], repo_type='dataset', revision=sys.argv[3], token=os.environ.get('GREENLAB_HF_TOKEN') or os.environ.get('HF_TOKEN')))" Green-Lab/2026-10-16-111868-agentic-traces "$(basename "$rel")" "$rev") || exit 1
  # a link, not a copy: the job tars the workspace root back to the runner, and each trace is 1.4 GB
  dst="$BENCH_DIR/datasets/$(basename "$rel")"; ln -sf "$src" "$dst"
  got=$(sha256sum "$dst" | cut -d' ' -f1)
  [ "$want" = "$got" ] || { echo "dataset sha256 $got != recorded LIVEKIT_${v}_SHA $want" >&2; exit 1; }
done

sed -i "s|/bench/|$BENCH_DIR/|g" "$BENCH_DIR/run.env" "$BENCH_DIR"/launches/*/launch.env
sed -i 's|^EXECUTOR=.*|EXECUTOR=ci|; s|^PORT=.*|PORT='"$PORT"'|' "$BENCH_DIR/run.env"
for f in "$BENCH_DIR"/launches/*/launch.env; do
  if grep -q '^WORKLOAD=livekit$' "$f"; then sed -i 's|^POINTS=.*|POINTS="$CONC:0"|' "$f"; else rm -rf "$(dirname "$f")"; fi
done
bash "$BENCH_DIR/recipes/run_cell.sh"; rc=$?
# one server per CI job: keep this job's log next to its point, so another job's log never stands in for it
for p in "$BENCH_DIR"/points/*/; do
  k=$(basename "$p"); l="${k%-c*}"
  cp "$BENCH_DIR/launches/$l/server.log" "$p/server.log" 2>/dev/null || true
done
OUT="${RESULT_DIR:-$INFMAX_CONTAINER_WORKSPACE/results}/bench"
mkdir -p "$OUT" && cp -r "$BENCH_DIR/points" "$BENCH_DIR/launches" "$BENCH_DIR/status.json" "$OUT/"
raw=$(ls "$BENCH_DIR"/points/*/raw/agg.json 2>/dev/null | head -1)
[ -n "$raw" ] && cp "$raw" "$INFMAX_CONTAINER_WORKSPACE/$RESULT_FILENAME.json"
art=$(ls -d "$BENCH_DIR"/points/*/raw/aiperf_artifacts "$BENCH_DIR"/points/*/aiperf 2>/dev/null | head -1)
[ -n "$art" ] && mkdir -p "$INFMAX_CONTAINER_WORKSPACE/results" && cp -r "$art" "$INFMAX_CONTAINER_WORKSPACE/results/"
exit $rc
